The naive approach of generating and checking all permutations becomes computationally expensive as \( n \) increases, making it infeasible for larger \( n \). We can optimize this by using a backtracking approach to find the valid sequences without checking all permutations.

Let's implement this optimized approach.
```python
def find_sequence(n, sequence, used, valid_pairs):
    if len(sequence) == n:
        return sequence

    last_number = sequence[-1]
    for pair in valid_pairs[last_number]:
        if not used[pair]:
            used[pair] = True
            result = find_sequence(n, sequence + [pair], used, valid_pairs)
            if result:
                return result
            used[pair] = False
    return None

def generate_valid_pairs(n):
    valid_pairs = {i: [] for i in range(1, n + 1)}
    for i, j in itertools.combinations(range(1, n + 1), 2):
        if is_perfect_square(i + j):
            valid_pairs[i].append(j)
            valid_pairs[j].append(i)
    return valid_pairs

def find_smallest_n():
    n = 2
    while True:
        valid_pairs = generate_valid_pairs(n)
        for start in range(1, n + 1):
            sequence = [start]
            used = {i: False for i in range(1, n + 1)}
            used[start] = True
            result = find_sequence(n, sequence, used, valid_pairs)
            if result:
                return n, result
        n += 1

# Find and print the smallest value of n with a valid sequence
smallest_n, sequence = find_smallest_n()
print((smallest_n, sequence))
```
